import sys
from datetime import date, timedelta


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def is_weekday_and_not_holiday(day):
    return day.weekday() < 5 and day not in holidays


def main():
    holidays = set()
    allowance = {}
    used = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "holiday":
            holidays.add(parse(parts[1]))
        elif parts[0] == "allowance":
            allowance[parts[1]] = int(parts[2])
        elif parts[0] == "leave":
            first, last = parse(parts[2]), parse(parts[3])
            count = 0
            for offset in range((last - first).days + 1):
                day = first + timedelta(days=offset)
                if is_weekday_and_not_holiday(day):
                    count += 1
            used[parts[1]] = used.get(parts[1], 0) + count
    for name in sorted(used):
        u = used[name]
        a = allowance.get(name, 0)
        if u <= a:
            print(f"{name} used {u} left {a - u}")
        else:
            print(f"{name} used {u} over {u - a}")


if __name__ == "__main__":
    main()
